function toResponse(error) {
  const e = typeof error === "object" && error !== null ? error : {};
  const clientError = typeof e.statusCode === "number" && e.statusCode >= 400 && e.statusCode <= 499;
  if (clientError && e.expose === true && typeof e.message === "string") {
    return { status: e.statusCode, body: { error: e.message, ...(typeof e.code === "string" ? { code: e.code } : {}) } };
  }
  return { status: 500, body: { error: "Internal Server Error" } };
}

