function createShutdown(steps) {
  let stopping = false;
  return (name) => {
    if (stopping) {
      console.log(`Received ${name} again: already shutting down.`);
      return;
    }
    stopping = true;
    console.log(`Received ${name}: shutting down.`);
    for (const step of steps) step();
  };
}

const onSignal = createShutdown([
  () => console.log("drain integrations"),
  () => console.log("stop http server"),
  () => console.log("stop runtime"),
]);
