function createOrder(body, service) {
  const issues = [];
  if (typeof body?.item !== "string" || body.item.length === 0) issues.push("item");
  if (!Number.isInteger(body?.qty) || body.qty < 1) issues.push("qty");
  if (issues.length > 0) return { status: 400, issues };
  return { status: 201, data: service.create(body) };
}

